"""Offline English HTML reporting for IsoImpact (bundled into IsoImpact.py)."""
import base64
import html
import json
import math
from pathlib import Path
import zlib


def _report_asset(name):
    embedded = globals().get('_ISOIMPACT_REPORT_ASSETS')
    if embedded is not None:
        return zlib.decompress(base64.b85decode(embedded[name])).decode('utf-8')
    return (Path(__file__).parent / name).read_text(encoding='utf-8')


def _report_number(value):
    try:
        value = float(value)
    except (TypeError, ValueError, OverflowError):
        return None
    return value if math.isfinite(value) else None


def _report_correlations(values):
    """Spearman rho across isoforms, retaining missing/constant columns as NA.

    Every defined coefficient uses the same set of input isoforms. A feature
    with any missing value, or with no variation, has undefined correlations.
    Average ranks handle ties; no SciPy or new runtime dependency is required.
    """
    import numpy as np
    import pandas as pd

    matrix = np.asarray(values, dtype=float)
    n, p = matrix.shape
    complete = np.isfinite(matrix).all(axis=0)
    valid = np.zeros(p, dtype=bool)
    if n >= 2:
        valid[complete] = np.ptp(matrix[:, complete], axis=0) > 0
    correlation = np.full((p, p), np.nan, dtype=np.float32)
    indices = np.flatnonzero(valid)
    if len(indices):
        ranks = pd.DataFrame(matrix[:, indices]).rank(axis=0, method='average').to_numpy(dtype=float, copy=True)
        ranks -= ranks.mean(axis=0)
        ranks /= np.sqrt(np.sum(ranks * ranks, axis=0))
        correlation[np.ix_(indices, indices)] = np.clip(ranks.T @ ranks, -1.0, 1.0)
    upper = correlation[np.triu_indices(p, k=1)].astype('<f4', copy=False)
    return {
        'current': base64.b64encode(upper.tobytes()).decode('ascii'),
        'currentDiagonal': valid.tolist(),
        'undefinedFeatures': int((~valid).sum()),
        'definedPairs': int(np.isfinite(upper).sum()),
    }


def write_html_report(path, transcripts, tx_info, sequences, feature_values,
                      domains, feature_names, top_n=15,
                      reference_role='Reference', alternative_role='Alternative'):
    """Write a self-contained report from this run's actual extracted results."""
    import numpy as np

    reference = json.loads(_report_asset('isoimpact_reference.json'))
    metadata = reference['features']
    if set(feature_names) != {f['name'] for f in metadata} or len(feature_names) != 966:
        raise ValueError('HTML reference data require the fixed 966-feature schema.')
    if len(transcripts) < 2 or len(set(transcripts)) != len(transcripts):
        raise ValueError('HTML reporting requires at least two distinct isoforms.')
    chroms = {tx_info[tx]['chrom'] for tx in transcripts}
    strands = {tx_info[tx]['strand'] for tx in transcripts}
    if len(chroms) != 1 or len(strands) != 1:
        raise ValueError('Transcript tracks must share one chromosome and strand.')

    first = tx_info[transcripts[0]]
    gene = first.get('gene_name') or first.get('gene_id') or 'IsoImpact'
    samples = []
    for i, tx in enumerate(transcripts):
        pid = tx_info[tx]['protein_id']
        role = reference_role if i == 0 else (
            alternative_role if len(transcripts) == 2 else f'{alternative_role} {i}')
        samples.append({'transcript': tx, 'protein': pid,
                        'length': len(sequences[pid]), 'role': role})

    features = []
    raw_columns = []
    for meta in metadata:
        name = meta['name']
        values = [_report_number(feature_values[tx].get(name)) for tx in transcripts]
        base = values[0]
        relative = []
        for value in values:
            relative.append(_report_number((value - base) / base)
                            if value is not None and base not in (None, 0) else None)
        changes = [abs(value) for value in relative[1:] if value is not None]
        features.append({**meta, 'values': values, 'relative': relative,
                         'maxChange': max(changes) if changes else None,
                         'zeroReference': base == 0})
        raw_columns.append([np.nan if v is None else v for v in values])
    correlations = _report_correlations(np.asarray(raw_columns).T)

    protein_ids = {sample['protein'] for sample in samples}
    selected_domains = []
    for row in domains.to_dict(orient='records'):
        if str(row['Protein_ID']) not in protein_ids:
            continue
        start, end = _report_number(row['Genomic_Start']), _report_number(row['Genomic_End'])
        if start is None or end is None or not start.is_integer() or not end.is_integer():
            continue
        start, end = sorted((int(start), int(end)))
        if start < 1:
            continue
        selected_domains.append({
            'Protein_ID': str(row['Protein_ID']), 'Domain_ID': str(row['Domain_ID']),
            'Domain_Name': str(row['Domain_Name']), 'Genomic_Start': start, 'Genomic_End': end,
        })
    palette = ['#eda45e', '#59bea2', '#998abd', '#e8735a', '#87ceeb', '#ffb347',
               '#77dd77', '#dda0dd', '#48d1cc', '#f08080', '#aec6cf', '#c8a96a']
    names = sorted({row['Domain_Name'] for row in selected_domains})
    structure = {
        'chrom': next(iter(chroms)), 'strand': next(iter(strands)),
        'transcripts': {tx: tx_info[tx]['records'] for tx in transcripts},
        'domains': selected_domains,
        'domainColors': {name: palette[i % len(palette)] for i, name in enumerate(names)},
    }
    p = len(features)
    payload = {
        'gene': gene, 'n': len(samples), 'p': p, 'pairs': p * (p - 1) // 2,
        'samples': samples, 'features': features, 'families': reference['families'],
        'featureOrder': list(feature_names), 'topN': top_n,
        'reference': reference['reference'], 'referenceN': reference['referenceN'],
        'referenceInfo': reference['referenceInfo'], 'structure': structure,
        **correlations,
    }
    # Do not let an annotation value terminate the JSON script element.
    encoded = json.dumps(payload, ensure_ascii=False, allow_nan=False, separators=(',', ':'))
    for character, escape in [('<', r'\u003c'), ('>', r'\u003e'), ('&', r'\u0026'),
                              ('\u2028', r'\u2028'), ('\u2029', r'\u2029')]:
        encoded = encoded.replace(character, escape)
    template = _report_asset('isoimpact_report_template.html')
    document = template.replace('__ISOIMPACT_GENE__', html.escape(gene, quote=True))
    document = document.replace('__ISOIMPACT_SAMPLE_COUNT__', str(len(samples)))
    document = document.replace('__ISOIMPACT_DATA__', encoded)
    path = Path(path)
    temporary = path.with_name(path.name + '.writing')
    with temporary.open('w', encoding='utf-8', newline='\n') as handle:
        handle.write(document)
    temporary.replace(path)
    return path

